local WindowManager = require(script.Parent.Parent.WindowManager)
local Component = require(script.Parent.Component)
local Prefab = require(script.Parent.Prefab)
local PrefabLoader = require(script.Parent.Prefab.Loader)
local ViewModel = require(script.Parent.ViewModel)
local Connection = require(script.Parent.Parent.Connection)

local Player = game.Players.LocalPlayer
local module = {}
module.__index = module

-- 创建新的View实例
function module.new(viewScript, parent)
    -- 初始化self
    local self = (typeof(viewScript) == "Instance" and require(viewScript)) or 
                 (typeof(viewScript) == "table" and viewScript) or 
                 {}
    
    -- 定义元表
    local mt = {
        _script = viewScript,
        _parent = parent,
        _parentView = nil,
        _dataContext = nil,
        _usingDataContext = nil,
        _effects = {},
        _disables = {},
        
        -- 获取数据上下文
        _getDataContext = function(self)
            if not self._dataContext then
                local viewFolder = viewScript and viewScript:FindFirstAncestorWhichIsA("Folder")
                local vmScript = viewFolder and viewFolder:FindFirstAncestorWhichIsA("ModuleScript")
                if vmScript then
                    self._dataContext = require(vmScript)
                end
            end
            return self._dataContext
        end,
        
        -- 获取父视图
        _getParentView = function(self)
            if (not self._parentView) and self._parent then
                self._parentView = require(self._parent)
            end
            return self._parentView
        end,
        
        -- 设置使用的数据上下文
        _using = function(self, vm)
            self._usingDataContext = vm
        end,
        
        -- 生命周期方法
        Load = function() end,
        Start = function() end
    }
    
    -- 合并module和self到mt
    for i, v in pairs(module) do mt[i] = v end
    for i, v in pairs(self) do
        mt[i] = v

		-- 处理特殊方法名（OnOpen_, OnClose_, OnShow_, OnHide_）
        if string.find(i, "OnOpen_") == 1 then
            local windowName = string.gsub(i, "OnOpen_", "")
            WindowManager:OnWindowOpened(windowName, function(...)
                v(self, ...)
            end)
        elseif string.find(i, "OnClose_") == 1 then
            local windowName = string.gsub(i, "OnClose_", "")
            WindowManager:OnWindowClosed(windowName, function(...)
                v(self, ...)
            end)
		elseif string.find(i, "OnShow_") == 1 then
            local panelName = string.gsub(i, "OnShow_", "")
            WindowManager:OnPanelShown(panelName, function(...)
                v(self, ...)
            end)
		elseif string.find(i, "OnHide_") == 1 then
            local panelName = string.gsub(i, "OnHide_", "")
            WindowManager:OnPanelHidden(panelName, function(...)
                v(self, ...)
            end)
        end
    end

    -- 设置元表
    setmetatable(self, {
        __index = function(t, k)
            if k == "DataContext" then 
                return rawget(t, "_usingDataContext") or mt:_getDataContext()
            elseif k == "Parent" then
                return mt:_getParentView()
            end
            return mt[k] or rawget(t, k)
        end
    })
    
    -- 初始化操作
    self:AdjustButtonHover("Scale")
    self:Load()
    self:_connectOnModel()
    return self
end

-- 连接模型事件
function module:_connectOnModel()
    for i, v in pairs(self) do
        if typeof(i) == "string" and string.find(i, "On_") == 1 then
            local name = string.gsub(i, "On_", ""):gsub("_", ".")
            self:Connect(name, function(...) v(self, ...) end)
        end
    end
end

-- 设置可连接属性
function module:SetConnectable(symbol)
    return self.DataContext:_setConnectable(symbol)
end

-- 设置可绑定属性
function module:SetBindable(symbol)
    return self.DataContext:_setBindable(symbol)
end

-- 检查作用域并调整函数
function module:_checkScope(scope, ...)
    local args = {...}
    for i, v in ipairs(args) do
        if typeof(v) == "function" then
            for j, k in pairs(self) do
                if v == k then
                    args[i] = function(...)
                        if not self._disables[scope] then
                            return k(self, ...)
                        end
                    end
                    break
                end
            end
        end
    end
    return table.unpack(args)
end

-- 连接事件
function module:Connect(...): typeof(Connection)
    local connection = self.DataContext:_connect(self:_checkScope("Connect", ...))
    return connection
end

-- 延迟连接（占位函数）
function module:LateConnect(...)
    -- 实现延迟连接逻辑
end

-- 绑定命令
function module:Bind(cmdName, ...): typeof(Connection)
    self:_setBtnHover(...)
    local connection = self.DataContext:_bind(cmdName, self:_checkScope("Bind", ...))
    return connection
end

-- 命令后处理
function module:After(cmdName, ...): typeof(Connection)
    local connection = self.DataContext:_after(cmdName, self:_checkScope("After", ...))
    return connection
end

-- 解绑
function module:Unbind(signalName)
    if typeof(signalName) == "function" then
        for i, v in pairs(self) do
            if v == signalName then
                self[i], self._effects[i] = self._effects[i], nil
                return
            end
        end
    end
    return self.DataContext:_unbind(signalName)
end

-- 解绑
function module:Disconnect(signalName)
    return self:Unbind(signalName)
end

-- 添加效果
function module:Effect(propertyPath, func)
    for i, v in pairs(self) do
        if v == func then
            self._effects[i] = v
            self[i] = function(...)
                local value = v(...)
                local path = string.split(propertyPath, ".")
                local modelName = table.remove(path, 1)
                local model = self.DataContext[modelName]
                if model then
                    local key = table.remove(path, 1)
                    model[key] = value
                end
            end
            break
        end
    end
end

-- 使用数据上下文
function module:UseDataContext(vmName, func)
    local vm = ViewModel:_getViewModel(vmName)
    if func and vm then
        local t = setmetatable({DataContext = vm}, module)
        func(t)
    else
        self:_using(vm)
    end
end

-- Using 方法别名
module.Using = module.UseDataContext

-- 结束使用数据上下文
function module:UsingEnd()
    self:_using(nil)
end

-- 设置数据上下文（占位函数）
function module:SetDataContext(vmName)
    -- 实现设置数据上下文的逻辑
end

-- 获取组件
function module:GetComponent(uiObj, component, ...)
    return Component.Get(uiObj, component, ...)
end

-- 检查是否有组件
function module:HasComponent(uiObj, component)
    if typeof(uiObj) == "string" then
        component, uiObj = uiObj, self
    end
    return Component.Has(uiObj, component)
end

-- 设置禁用状态（占位函数）
function module:SetDisabled(obj)
    -- 实现设置禁用状态的逻辑
end

-- 获取节点
function module:GetNode(objName, ...)
    return Prefab.Get(objName, ...)
end

-- 放置节点
function module:PutNode(obj, ...)
    return Prefab.Put(obj, ...)
end

-- 获取UI对象
function module:GetUI(path, parent): Instance
    local obj = parent or Player
    for _, name in ipairs(string.split(path, ".")) do
        obj = obj:FindFirstChild(name) or obj:WaitForChild(name, 10)
        if not obj then 
            warn("Not found UI " .. path)
            return nil 
        end
    end
    return obj
end

-- 调整按钮悬停效果
function module:AdjustButtonHover(animationType)
    self._btnHoverType = animationType
end

-- 设置按钮悬停效果
function module:_setBtnHover(...)
    for _, v in ipairs({...}) do
        if typeof(v) == "Instance" and (v:IsA("ImageButton") or v:IsA("TextButton")) then
            local comp = self:GetComponent(v, "Button")
            if comp.Dispose then
                comp:Dispose()
            end
            if self._btnHoverType then
                if comp.Init then
                    comp:Init(self._btnHoverType)
                end
            end
            break
        end
    end
end

-- 设置内容
function module:SetContent(ui)
    self.Content = ui
end

-- 获取内容
function module:GetContent()
    return self.Content
end

-- 启用连接
function module:EnableConnect()
    self._disables.Connect = nil
end

-- 禁用连接
function module:DisableConnect()
    self._disables.Connect = true
end

-- 启用绑定
function module:EnableBind()
    self._disables.Bind = nil
end

-- 禁用绑定
function module:DisableBind()
    self._disables.Bind = true
end

-- 启用命令后处理
function module:EnableAfter()
    self._disables.After = nil
end

-- 禁用命令后处理
function module:DisableAfter()
    self._disables.After = true
end

-- 启用所有连接
function module:Enable()
    self:EnableConnect()
    self:EnableBind()
    self:EnableAfter()
end

-- 禁用所有连接
function module:Disable()
    self:DisableConnect()
    self:DisableBind()
    self:DisableAfter()
end

function module:RegisterAs(type: "Window" | "Container" | "Panel" | "Prefab" | "Component", name: string?)
    name = name or self._script.Name
    if type == "Container" then
        WindowManager:RegisterViewAsContainer(self, name)
    elseif type == "Panel" then
        WindowManager:RegisterViewAsPanel(self, name)
    elseif type == "Window" then
        WindowManager:RegisterViewAsWindow(self, name)
    elseif type == "Prefab" then
        PrefabLoader.LoadPrefab(name, {
            Clone = function()
                local clone = self._script:Clone()
                local cloneModule = require(clone)
                cloneModule.Content = self:GetContent():Clone()
                cloneModule.DataContext = self.DataContext
                cloneModule.RegisterAs = function()
                    return
                end
                cloneModule.SetContent = function()
                    return
                end
                cloneModule.Start = function()
                    return
                end
                local view = module.new(clone, self._parent)
                return view.Content, view
            end
        })
    elseif type == "Component" then
        local clone = self._script
        local cloneModule = require(clone)
        cloneModule.RegisterAs = function()
            return
        end
        cloneModule.GetContent = function(self)
            return self._element
        end
        Component.LoadComponent(name, cloneModule)
    end
end

return module